// ─── File: AbaDemo.java ───
// Runnable demo. In a real project each class lives in its own file.
package com.bank.pool;

import java.util.concurrent.atomic.AtomicStampedReference;
import java.util.logging.*;

public class AbaDemo {
    private static final Logger LOG = Logger.getLogger("Pool");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        LOG.setUseParentHandlers(false);
        LOG.addHandler(h);
        LOG.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SlipFreeList freeList = new SlipFreeList(LOG);
        Slip a = new Slip("SLIP-A");
        Slip b = new Slip("SLIP-B");
        freeList.push(a);          // stamp 1
        freeList.push(b);          // stamp 2

        // Thread-1 reads the top (A... actually B on top) and its stamp, then is "preempted".
        int[] holder = new int[1];
        Slip observed = freeList.peek(holder);
        int observedStamp = holder[0];
        LOG.info(() -> "thread-1 observed top=" + observed.id() + " stamp=" + observedStamp);

        // Meanwhile Thread-2 performs the ABA round trip: pop B, pop A, push B back.
        freeList.pop();            // removes B  (stamp 3)
        freeList.pop();            // removes A  (stamp 4)
        freeList.push(b);          // pushes B back → top is B again (stamp 5)
        LOG.info("thread-2 did pop,pop,push → value is B again but stamp advanced");

        // Thread-1 resumes and tries a stamped CAS with its STALE stamp.
        boolean success = freeList.casTop(observed, observed.next(), observedStamp, observedStamp + 1);
        LOG.info(() -> "thread-1 stamped CAS success? " + success + "  (expected false — ABA detected)");
    }
}

// ─── Would be in model/Slip.java ───
class Slip {
    private final String id;
    private Slip next;       // free-list link
    Slip(String id) { this.id = id; }
    String id() { return id; }
    Slip next() { return next; }
    void setNext(Slip n) { this.next = n; }
}

// ─── Would be in freelist/SlipFreeList.java ───
class SlipFreeList {
    // Reference paired with an int stamp (version). Start stamp 0.
    private final AtomicStampedReference<Slip> top = new AtomicStampedReference<>(null, 0);
    private final Logger log;
    SlipFreeList(Logger log) { this.log = log; }

    void push(Slip slip) {
        int[] holder = new int[1];
        Slip current;
        do {
            current = top.get(holder);         // read ref + stamp together
            slip.setNext(current);
        } while (!top.compareAndSet(current, slip, holder[0], holder[0] + 1)); // bump stamp
        log.info(() -> "pushed " + slip.id() + " stamp now " + top.getStamp());
    }

    Slip pop() {
        int[] holder = new int[1];
        Slip current, next;
        do {
            current = top.get(holder);
            if (current == null) return null;
            next = current.next();
        } while (!top.compareAndSet(current, next, holder[0], holder[0] + 1)); // bump stamp
        log.info(() -> "popped " + current.id() + " stamp now " + top.getStamp());
        return current;
    }

    Slip peek(int[] stampHolder) { return top.get(stampHolder); }

    // Exposed for the demo: a stamped CAS that fails if the stamp advanced (ABA).
    boolean casTop(Slip expectedRef, Slip newRef, int expectedStamp, int newStamp) {
        return top.compareAndSet(expectedRef, newRef, expectedStamp, newStamp);
    }
}
