// ─── File: src/test/java/com/bank/pool/freelist/SlipFreeListTest.java ───
package com.bank.pool.freelist;

import com.bank.pool.model.Slip;
import org.junit.jupiter.api.Test;
import java.util.logging.Logger;
import static org.junit.jupiter.api.Assertions.*;

class SlipFreeListTest {
    @Test
    void staleStampedCasFailsAfterAbaRoundTrip() {
        SlipFreeList list = new SlipFreeList(Logger.getLogger("t"));
        Slip a = new Slip("A"); Slip b = new Slip("B");
        list.push(a); list.push(b);
        int[] holder = new int[1];
        Slip observed = list.peek(holder);
        int staleStamp = holder[0];
        list.pop(); list.pop(); list.push(b);              // ABA: value B returns
        assertFalse(list.casTop(observed, observed.next(), staleStamp, staleStamp + 1));
    }
}
